import functools
from typing import ForwardRef, Any
from fastapi import FastAPI, Depends
from fastapi.dependencies.utils import get_typed_signature

def test_wrapped_method_type_inference():
    app = FastAPI()

    class Model:
        def __init__(self, name: str):
            self.name = name

    def wrapper(func):
        @functools.wraps(func)
        def wrapped(*args, **kwargs):
            return func(*args, **kwargs)
        return wrapped

    @wrapper
    def endpoint(item: "Model"):
        return {"item": item}

    # This should not raise NameError
    signature = get_typed_signature(endpoint)
    assert "item" in signature.parameters
EOF
python3 -m pytest tests/test_wrapped_method_forward_reference.py
